$top20Files = $files | Select-Object -First $top20PercentCount
$top20Size = ($top20Files | Measure-Object -Property Length -Sum).Sum

$videos = $top20Files | Where-Object { $_.Extension -match '\.(mp4|mov|avi|mkv)$' }
$images = $top20Files | Where-Object { $_.Extension -match '\.(jpg|jpeg|png|heic)$' }

[PSCustomObject]@{
    TotalFilesOver1MB = $totalCount
    TotalSizeGB = [math]::Round($totalSize / 1GB, 2)
    Top20PercentCount = $top20PercentCount
    Top20SizeGB = [math]::Round($top20Size / 1GB, 2)
    PercentageOfTotalSize = [math]::Round(($top20Size / $totalSize) * 100, 2)
    Top20VideosCount = @($videos).Count
    Top20ImagesCount = @($images).Count
} | ConvertTo-Json

$sourceDir = "C:\mom phone storage"
$destDir = "C:\mom phone storage compressed"
$deleteList = "$destDir\delete_list.md"

# Create destination folder and delete list if they don't exist
if (!(Test-Path $destDir)) { New-Item -ItemType Directory -Path $destDir | Out-Null }
if (!(Test-Path $deleteList)) { Set-Content -Path $deleteList -Value "# Safe to Delete`nThese files have been successfully compressed and saved to the compressed folder.`n" }

# Get top 20% files > 1MB
Write-Host "Scanning files..."
$files = Get-ChildItem -Path $sourceDir -File -Recurse | Where-Object { $_.Length -ge 1MB } | Sort-Object Length -Descending
$totalCount = $files.Count
if ($totalCount -eq 0) { 
    Write-Host "No files found."
    exit 
}

$top20PercentCount = [math]::Round($totalCount * 0.2)
if ($top20PercentCount -eq 0) { $top20PercentCount = 1 }

$top20Files = $files | Select-Object -First $top20PercentCount
Write-Host "Found $totalCount files. Compressing top $top20PercentCount largest files..."

$count = 0
foreach ($file in $top20Files) {
    $count++
    $relativePath = $file.FullName.Substring($sourceDir.Length + 1)
    $destFile = Join-Path $destDir $relativePath
    $destFolder = Split-Path $destFile -Parent

    if (!(Test-Path $destFolder)) { New-Item -ItemType Directory -Path $destFolder | Out-Null }

    # If already compressed previously, skip
    if (Test-Path $destFile) { 
        Write-Host "[$count/$top20PercentCount] Skipping, already exists: $($file.Name)"
        continue 
    }

    $ext = $file.Extension.ToLower()
    $success = $false

    Write-Host "[$count/$top20PercentCount] Compressing: $($file.Name)"

    if ($ext -match '\.(mp4|mov|avi|mkv)$') {
        # Compress video (H.264, CRF 28 for good compression, fast preset)
        $process = Start-Process -FilePath "ffmpeg" -ArgumentList "-i `"$($file.FullName)`" -vcodec libx264 -crf 28 -preset fast -y `"$destFile`"" -Wait -NoNewWindow -PassThru
        if ($process.ExitCode -eq 0) { $success = $true }
    }
    elseif ($ext -match '\.(jpg|jpeg|png|heic)$') {
        # Compress image (Q 8 for JPEG/WEBP, limits quality loss but saves space)
        if ($ext -eq ".png") {
            # PNGs compressed to JPEG to save space
            $destFile = $destFile -replace '\.png$', '.jpg'
            $process = Start-Process -FilePath "ffmpeg" -ArgumentList "-i `"$($file.FullName)`" -q:v 8 -y `"$destFile`"" -Wait -NoNewWindow -PassThru
        } else {
            $process = Start-Process -FilePath "ffmpeg" -ArgumentList "-i `"$($file.FullName)`" -q:v 8 -y `"$destFile`"" -Wait -NoNewWindow -PassThru
        }
        if ($process.ExitCode -eq 0) { $success = $true }
    }

    if ($success) {
        # Only log the original file as safe to delete if compression exited successfully
        Add-Content -Path $deleteList -Value "- $($file.FullName)"
    } else {
        Write-Host "Failed to compress: $($file.Name)"
    }
}
Write-Host "Bulk compression complete."

